import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('balanceDue with no payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const due = balanceDue(invoice);
  assert.equal(due, 60500); // 50000 + 21% VAT
});

test('balanceDue with partial payment', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [{ amount: 30000, date: '2026-10-07' }],
  };
  const due = balanceDue(invoice);
  assert.equal(due, 30500); // 60500 - 30000
});

test('balanceDue with full payment', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [{ amount: 60500, date: '2026-10-07' }],
  };
  const due = balanceDue(invoice);
  assert.equal(due, 0);
});

test('balanceDue with multiple partial payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [
      { amount: 20000, date: '2026-10-07' },
      { amount: 20000, date: '2026-10-10' },
    ],
  };
  const due = balanceDue(invoice);
  assert.equal(due, 20500); // 60500 - 40000
});

test('recordPayment rejects draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const result = recordPayment(invoice, { amount: 10000, date: '2026-10-07' });
  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment rejects non-integer amounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 10000.5, date: '2026-10-07' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects zero amount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 0, date: '2026-10-07' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects negative amount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: -10000, date: '2026-10-07' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects overpayment', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 70000, date: '2026-10-07' });
  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment on issued invoice sets status to partially_paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 30000, date: '2026-10-07' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'partially_paid');
});

test('recordPayment on issued invoice to full payment sets status to paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 60500, date: '2026-10-07' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment on partially_paid invoice to full payment sets status to paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [{ amount: 30000, date: '2026-10-07' }],
  };
  const result = recordPayment(invoice, { amount: 30500, date: '2026-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment on partially_paid invoice to partial payment keeps status as partially_paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [{ amount: 30000, date: '2026-10-07' }],
  };
  const result = recordPayment(invoice, { amount: 10000, date: '2026-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'partially_paid');
});

test('recordPayment creates payments array if missing', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 30000, date: '2026-10-07' });
  assert.equal(result.ok, true);
  assert.equal(Array.isArray(result.value.payments), true);
  assert.equal(result.value.payments.length, 1);
});

test('recordPayment preserves existing payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [
      { amount: 10000, date: '2026-10-07' },
      { amount: 10000, date: '2026-10-08' },
    ],
  };
  const result = recordPayment(invoice, { amount: 10000, date: '2026-10-09' });
  assert.equal(result.ok, true);
  assert.equal(result.value.payments.length, 3);
  assert.deepEqual(result.value.payments[0], { amount: 10000, date: '2026-10-07' });
  assert.deepEqual(result.value.payments[1], { amount: 10000, date: '2026-10-08' });
  assert.deepEqual(result.value.payments[2], { amount: 10000, date: '2026-10-09' });
});

test('recordPayment adds new payment with correct amount and date', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 25000, date: '2026-10-08' });
  assert.equal(result.ok, true);
  assert.deepEqual(result.value.payments[0], { amount: 25000, date: '2026-10-08' });
});

test('recordPayment does not mutate original invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const originalStatus = invoice.status;
  recordPayment(invoice, { amount: 30000, date: '2026-10-07' });
  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.payments, undefined);
});

test('recordPayment preserves invoice number', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 30000, date: '2026-10-07' });
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
});

test('recordPayment rejects overpayment on partially_paid invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [{ amount: 30000, date: '2026-10-07' }],
  };
  const result = recordPayment(invoice, { amount: 50000, date: '2026-10-08' });
  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('balanceDue is zero after invoice is paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'paid',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
    payments: [{ amount: 60500, date: '2026-10-07' }],
  };
  const due = balanceDue(invoice);
  assert.equal(due, 0);
});

test('recordPayment correctly updates balanceDue', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DESK', name: 'Desk', qty: 1, unitPrice: 50000, vatRate: 21, discountPercent: 0 },
    ],
    number: 'INV-2026-0001',
  };
  const result = recordPayment(invoice, { amount: 30000, date: '2026-10-07' });
  assert.equal(result.ok, true);
  const due = balanceDue(result.value);
  assert.equal(due, 30500); // 60500 - 30000
});

test('recordPayment with discount invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
